1	//! The pages the browser lands on at the end of an overlay sign-in, served by
2	//! the localhost listener in `main.rs`. This is the hand-back point between the
3	//! hosted login page and the overlay, so it confirms the outcome and says
4	//! whether to close the tab.
5	//!
6	//! The same design is rendered by `cloudflare/auth-worker/src/handoff-page.ts`
7	//! and `src/auth-pages.ts`; the three copies exist because they run in three
8	//! different runtimes. Keep the copy and palette in sync when changing one.
9	
10	const STYLE: &str = r#":root{color-scheme:light}
11	*{box-sizing:border-box}
12	body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;
13	background:radial-gradient(900px 500px at 50% -20%,#fff 0%,#eef2f8 60%,#e3eaf4 100%);color:#0f172a;
14	font:15px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",sans-serif;-webkit-font-smoothing:antialiased}
15	.card{position:relative;overflow:hidden;width:min(100%,420px);padding:34px 28px 30px;text-align:center;
16	background:#fff;border:1px solid #e2e8f0;border-radius:16px;
17	box-shadow:0 20px 50px rgba(15,23,42,.12),0 8px 20px rgba(15,23,42,.06)}
18	.card::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;
19	background:linear-gradient(90deg,#2955c9 0%,#3772ff 38%,#3bb273 72%,#e6a830 100%)}
20	.badge{display:flex;align-items:center;justify-content:center;width:44px;height:44px;margin:0 auto 16px;border-radius:999px}
21	.badge svg{width:22px;height:22px}
22	[data-tone=ok] .badge{background:rgba(59,178,115,.14);color:#2e8f5c}
23	[data-tone=warn] .badge{background:rgba(223,41,53,.12);color:#b81f2a}
24	.eyebrow{margin:0 0 6px;font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#2955c9}
25	h1{margin:0 0 10px;font-size:23px;line-height:1.25;letter-spacing:-.01em}
26	.lead{margin:0;color:#475569}
27	.steps{margin:18px 0 0;padding:0;list-style:none;text-align:left;border-top:1px solid #e2e8f0}
28	.steps li{position:relative;margin:0;padding:10px 0 0 18px;font-size:13.5px;color:#475569}
29	.steps li:first-child{padding-top:14px}
30	.steps li::before{content:"";position:absolute;left:2px;top:18px;width:5px;height:5px;border-radius:999px;background:#cbd5e1}
31	.steps li:first-child::before{top:22px}
32	.hint{margin:16px 0 0;font-size:12.5px;color:#64748b}
33	code{font:600 12.5px/1.4 ui-monospace,"SF Mono",Menlo,monospace;background:#f3f6fb;border:1px solid #e2e8f0;border-radius:5px;padding:2px 5px;overflow-wrap:anywhere;-webkit-box-decoration-break:clone;box-decoration-break:clone}
34	@media (max-width:400px){.card{padding:28px 20px 24px}h1{font-size:21px}}"#;
35	
36	const CHECK_ICON: &str = r#"<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>"#;
37	const ALERT_ICON: &str = r#"<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.5h.01"/></svg>"#;
38	
39	pub fn escape_html(value: &str) -> String {
40	    let mut out = String::with_capacity(value.len());
41	    for character in value.chars() {
42	        match character {
43	            '&' => out.push_str("&amp;"),
44	            '<' => out.push_str("&lt;"),
45	            '>' => out.push_str("&gt;"),
46	            '"' => out.push_str("&quot;"),
47	            '\'' => out.push_str("&#39;"),
48	            _ => out.push(character),
49	        }
50	    }
51	    out
52	}
53	
54	/// Renders one self-contained Tui page — no external CSS, fonts, or images.
55	///
56	/// `lead`, `steps`, and `hint` are trusted HTML so copy can carry `<code>`
57	/// spans; the title is escaped. Escape request-derived text at the call site.
58	fn arcade_page(tone: &str, title: &str, lead: &str, steps: &[&str], hint: &str) -> String {
59	    let list = if steps.is_empty() {
60	        String::new()
61	    } else {
62	        format!(
63	            "<ul class=\"steps\">{}</ul>",
64	            steps
65	                .iter()
66	                .map(|step| format!("<li>{step}</li>"))
67	                .collect::<Vec<_>>()
68	                .join(""),
69	        )
70	    };
71	    let hint = if hint.is_empty() {
72	        String::new()
73	    } else {
74	        format!("<p class=\"hint\">{hint}</p>")
75	    };
76	    let icon = if tone == "ok" { CHECK_ICON } else { ALERT_ICON };
77	    format!(
78	        r#"<!doctype html>
79	<html lang="en">
80	<head>
81	<meta charset="utf-8">
82	<meta name="viewport" content="width=device-width, initial-scale=1">
83	<meta name="robots" content="noindex">
84	<title>Tui — {title_text}</title>
85	<style>{STYLE}</style>
86	</head>
87	<body>
88	<main class="card" data-tone="{tone}">
89	<span class="badge">{icon}</span>
90	<p class="eyebrow">Tui</p>
91	<h1>{title_text}</h1>
92	<p class="lead">{lead}</p>
93	{list}
94	{hint}
95	</main>
96	</body>
97	</html>"#,
98	        title_text = escape_html(title),
99	    )
100	}
101	
102	/// Success: the overlay has the token and is leaving the sign-in gate.
103	pub fn signed_in_page() -> String {
104	    arcade_page(
105	        "ok",
106	        "You're signed in",
107	        "Tui is unlocking now. You can close this tab and go back to the overlay.",
108	        &[],
109	        "Your session is saved on this machine, so Tui opens straight to the games next time.",
110	    )
111	}
112	
113	/// The handoff reached us but carried no usable session.
114	pub fn sign_in_failed_page(reason: &str) -> String {
115	    arcade_page(
116	        "warn",
117	        "Sign-in didn't finish",
118	        reason,
119	        &[
120	            "Go back to Tui and choose <b>Sign in</b> again.",
121	            "If your browser blocked the redirect back to Tui, allow pop-ups for the login page.",
122	            "Signing in with Google or GitHub? Approve the consent screen rather than closing it.",
123	        ],
124	        "Prefer the terminal? <code>gamepigeon auth login</code> signs in the same account.",
125	    )
126	}
127	
128	/// A redirect arrived for a sign-in attempt the overlay is no longer waiting on
129	/// — usually a stale tab from a cancelled or superseded attempt.
130	pub fn stale_attempt_page() -> String {
131	    arcade_page(
132	        "warn",
133	        "This sign-in link is out of date",
134	        "Tui is waiting on a newer sign-in, so this tab can't be used to finish it.",
135	        &[
136	            "Close this tab and finish in the most recent Tui sign-in tab.",
137	            "No other tab open? Go back to Tui and choose <b>Sign in</b> again.",
138	        ],
139	        "",
140	    )
141	}
142	
143	#[cfg(test)]
144	mod tests {
145	    use super::*;
146	
147	    #[test]
148	    fn escapes_html_in_page_titles_and_text() {
149	        assert_eq!(escape_html("a<b>&\"'"), "a&lt;b&gt;&amp;&quot;&#39;");
150	    }
151	
152	    #[test]
153	    fn success_page_is_a_branded_standalone_document() {
154	        let page = signed_in_page();
155	        assert!(page.starts_with("<!doctype html>"));
156	        assert!(page.contains("You&#39;re signed in"));
157	        assert!(page.contains("close this tab"));
158	        assert!(page.contains("Tui"));
159	        // Self-contained: nothing to fetch from the network.
160	        assert!(!page.contains("http://"));
161	        assert!(!page.contains("https://"));
162	    }
163	
164	    #[test]
165	    fn failure_pages_say_what_to_do_next() {
166	        let failed = sign_in_failed_page("The login page came back without a session token.");
167	        assert!(failed.contains("without a session token"));
168	        assert!(failed.contains("Sign in</b> again"));
169	
170	        let stale = stale_attempt_page();
171	        assert!(stale.contains("out of date"));
172	        assert!(stale.contains("Sign in</b> again"));
173	    }
174	
175	    #[test]
176	    fn failure_reason_is_escaped_by_the_caller_not_injected_raw() {
177	        // Callers escape request-derived text; the page must carry it verbatim
178	        // so already-escaped entities are not double-escaped.
179	        let page = sign_in_failed_page(&escape_html("<script>alert(1)</script>"));
180	        assert!(!page.contains("<script>"));
181	        assert!(page.contains("&lt;script&gt;"));
182	    }
183	}
