36	export function gateMarkup(): string {
37	  return `<section class="arcade-menu gate-screen">
38	    <header class="menu-heading gate-heading"><div><p>Welcome</p><h1>Tui</h1></div></header>
39	    <div class="gate-welcome">
40	      <p>Sign in to play a familiar game and keep your scores between sessions.</p>
41	    </div>
