46	      <div id="auth-fallback" class="auth-fallback" hidden>
47	        <button id="auth-copy-link" type="button" class="auth-fallback-button">Copy link</button>
48	        <code id="auth-fallback-url" class="auth-fallback-url"></code>
49	      </div>
50	    </div>
51	  </section>`;
52	}
53	
54	/** Persistent account indicator, top-left in the titlebar across every screen. */
55	export function renderAccountChip(): void {
56	  const chip = document.querySelector<HTMLButtonElement>("#account-chip");
57	  if (!chip) return;
58	  if (currentUser) {
59	    chip.hidden = false;
60	    chip.dataset.state = "in";
61	    chip.dataset.sync = syncError ? "error" : "ready";
62	    chip.title = syncError ?? "Click to sign out";
63	    chip.setAttribute(
64	      "aria-label",
65	      syncError
66	        ? `Signed in as ${currentUser.email}. ${syncError}`
67	        : `Signed in as ${currentUser.email}. Click to sign out.`,
68	    );
69	    chip.setAttribute("aria-haspopup", "dialog");
70	    // The chip is the only place the signed-in identity shows, so a paused sync
71	    // recolors it rather than overwriting the address — the state still reads
72	    // from the red dot/border and the tooltip.
73	    chip.innerHTML = `<span class="account-dot" aria-hidden="true"></span><span class="account-email">${
74	      escapeHtml(currentUser.email)
75	    }</span>`;
76	  } else {
77	    // Signed out: sign-in lives on the welcome gate; hide the titlebar chip.
78	    chip.hidden = true;
79	    chip.dataset.state = "out";
80	    delete chip.dataset.sync;
81	    chip.title = "";
82	    chip.removeAttribute("aria-label");
83	    chip.removeAttribute("aria-haspopup");
84	    chip.innerHTML = "";  }
85	}
86	
87	/**
88	 * Resets gate sign-in UI; controls live in {@link gateMarkup}, not the footer.
89	 * A pending attempt survives a gate re-render — its listener is still up, so
90	 * the fallback link has to come back with it rather than vanishing.
91	 */
92	export function renderSignInBar(): void {
93	  const status = document.querySelector<HTMLElement>("#auth-signin-status");
94	  if (currentUser) return;
95	  if (signInPending && pendingLoginUrl) {
96	    setSignInStatus("pending", pendingStatusMessage);
97	    showFallbackLink(pendingLoginUrl, pendingFallbackState);
98	    return;
99	  }
100	  if (status) {
101	    status.dataset.state = "idle";
102	    status.textContent = "";
103	  }
104	  hideFallbackLink();
105	}
106	
107	export function setSignInStatus(
108	  state: "idle" | "pending" | "error",
109	  message = "",
110	): void {
111	  const status = document.querySelector<HTMLElement>("#auth-signin-status");
112	  const button = document.querySelector<HTMLButtonElement>("#auth-signin");
113	  const cancelButton = document.querySelector<HTMLButtonElement>("#auth-signin-cancel");
114	  if (status) {
115	    status.dataset.state = state;
116	    status.textContent = message;
117	  }
118	  if (button) button.disabled = state === "pending";
119	  // The cancel button only makes sense while a browser handoff is pending —
120	  // it's how the user recovers if they closed that tab instead of finishing.
121	  if (cancelButton) cancelButton.hidden = state !== "pending";
122	}
123	
124	let signInPending = false;
125	/** The live attempt's login URL — same listener port and nonce Rust opened. */
126	let pendingLoginUrl: string | null = null;
127	let pendingBrowserOpened = true;
128	let pendingStatusMessage = "";
129	let pendingFallbackState: FallbackState = "backup";
130	
131	interface LoginHandoff {
132	  url: string;
133	  browserOpened: boolean;
134	}
135	
136	export interface SignInStart {
137	  started: boolean;
138	  /** False when every OS opener failed — the gate then stays put so the link is readable. */
139	  browserOpened: boolean;
140	}
141	
142	/** The URL of the attempt in flight, or null when nothing is pending. */
143	export function pendingSignInUrl(): string | null {
144	  return pendingLoginUrl;
145	}
146	
147	/** `failed` tints the fallback border when every browser opener failed. */
148	type FallbackState = "backup" | "failed";
149	
150	function showFallbackLink(url: string, state: FallbackState): void {
151	  const fallback = document.querySelector<HTMLElement>("#auth-fallback");
152	  const link = document.querySelector<HTMLElement>("#auth-fallback-url");
153	  if (!fallback) return;
154	  fallback.hidden = false;
155	  fallback.dataset.state = state;
156	  if (link) link.textContent = url;
157	}
158	
159	function hideFallbackLink(): void {
160	  const fallback = document.querySelector<HTMLElement>("#auth-fallback");
161	  if (!fallback) return;
162	  fallback.hidden = true;
163	  delete fallback.dataset.state;
164	  const link = document.querySelector<HTMLElement>("#auth-fallback-url");
165	  if (link) link.textContent = "";
166	  const copy = document.querySelector<HTMLButtonElement>("#auth-copy-link");
167	  if (copy) copy.textContent = "Copy link";
168	}
169	
170	/** Kicks off the browser sign-in handoff via the Rust command. */
171	export async function beginSignIn(): Promise<SignInStart> {
172	  if (signInPending) return { started: false, browserOpened: pendingBrowserOpened }; // one attempt at a time
173	  signInPending = true;
174	  setSignInStatus("pending", "Opening your browser...");
175	  try {
176	    // Older overlay binaries returned nothing; treat that as "browser opened"
177	    // so the gate keeps its previous behaviour instead of crying failure.
178	    const handoff = (await invoke<LoginHandoff | null>("start_auth_login")) ?? null;
179	    pendingLoginUrl = handoff?.url ?? null;
180	    pendingBrowserOpened = handoff?.browserOpened !== false;
181	    pendingStatusMessage = pendingBrowserOpened
182	      ? "Waiting for you to finish signing in..."
183	      : "Waiting for you to finish signing in in your browser.";
184	    setSignInStatus("pending", pendingStatusMessage);
185	    pendingFallbackState = pendingBrowserOpened ? "backup" : "failed";
186	    if (pendingLoginUrl) showFallbackLink(pendingLoginUrl, pendingFallbackState);
187	    return { started: true, browserOpened: pendingBrowserOpened };
188	  } catch (error) {
189	    signInPending = false;
190	    pendingLoginUrl = null;
191	    const message = error instanceof Error ? error.message : String(error);
192	    setSignInStatus("error", message || "Could not start sign-in. Try again.");
193	    return { started: false, browserOpened: false };
194	  }
195	}
196	
197	/** Copies the pending login URL; falls back to selecting it when the webview blocks the clipboard. */
198	export async function copySignInUrl(): Promise<boolean> {
199	  const url = pendingLoginUrl;
200	  if (!url) return false;
201	  try {
202	    await navigator.clipboard.writeText(url);
203	    return true;
204	  } catch {
205	    const link = document.querySelector<HTMLElement>("#auth-fallback-url");
206	    if (!link) return false;
207	    // Last resort: select the text so ⌘C/Ctrl+C works.
208	    const range = document.createRange();
209	    range.selectNodeContents(link);
210	    const selection = window.getSelection();
211	    selection?.removeAllRanges();
212	    selection?.addRange(range);
213	    return false;
214	  }
215	}
216	
217	/**
218	 * Abandons a pending sign-in — e.g. the user closed the browser tab instead
219	 * of finishing. Resets the gate immediately rather than waiting out the
220	 * backend's 300s timeout, and tells the backend to stop listening so a fresh
221	 * attempt isn't rejected as "already in progress."
222	 */
223	export async function cancelSignIn(): Promise<void> {
224	  if (!signInPending) return;
225	  signInPending = false;
226	  pendingLoginUrl = null;
227	  hideFallbackLink();
228	  setSignInStatus("idle", "");
229	  await invoke("cancel_auth_login");
230	}
231	
232	/** Clears the in-flight flag once an attempt resolves (success or failure). */
233	export function clearSignInPending(): void {
234	  signInPending = false;
235	  // The listener behind this URL is gone; a stale link would 404 or, worse,
236	  // look like it should still work.
237	  pendingLoginUrl = null;
238	  hideFallbackLink();
239	}
240	
241	/**
242	 * Removes the persisted session. Throws (leaving currentUser intact) if the
243	 * native deletion fails, so callers never report sign-out on retained
244	 * credentials.
245	 */
246	export async function signOut(): Promise<void> {
247	  await invoke("sign_out");
248	  currentUser = null;
249	  syncError = null;
250	}
251	
252	export function setSignedInUser(user: AuthUser): void {
253	  currentUser = user;
254	  syncError = null;
255	}
256	
257	export function setSyncError(message: string | null): void {
258	  syncError = message;
259	  renderAccountChip();
260	}
