/**
 * Reads one query parameter, treating a literal `?` as another `&`: some hosted
 * redirects append `?token=...` onto a callback that already carried `?state=...`,
 * yielding `state=..?token=..`. Values come back exactly as they arrived — the
 * token is a credential that round-trips through this listener verbatim.
 */
function callbackParam(query: string, key: string): string | null {
  for (const pair of query.split(/[&?]/)) {
    const separator = pair.indexOf("=");
    if (separator === -1) continue;
    if (pair.slice(0, separator) === key) return pair.slice(separator + 1);
  }
  return null;
}

/** Percent-decoding for human-readable query text (OAuth error descriptions). */
function decodeQueryText(value: string): string {
  try {
    return decodeURIComponent(value.replace(/\+/g, " "));
  } catch {
    return value.replace(/\+/g, " ");
  }
}

/**
 * The Worker percent-encodes the token into the callback's query, and the
 * listener hands back what it received, so decode once before spending it as a
 * bearer credential.
 */
function decodeCallbackToken(token: string): string {
  try {
    return decodeURIComponent(token);
  } catch {
    return token;
  }
}

/** Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
 * because it lands in both the browser page and the terminal. */
function callbackFailure(query: string): string | null {
  const error = callbackParam(query, "error");
  if (!error) return null;
