    return null;
  } catch {
    return null;
  }
}

function saveSession(sessionToken: string, user: AuthUser): void {
  if (!sessionToken) throw new Error("Auth did not return a session token.");
  if (!user.id || !user.email) throw new Error("Auth did not return a user.");
