/**
 * The pages the browser lands on during the CLI handoff, served by
 * `GET /cli/handoff`. This is the hand-back point between the signed-in browser
 * session and the CLI's localhost listener, so it either bounces onward or says
 * what to run next.
 *
 * The same design is rendered by `tauri/src/auth_pages.rs` and
 * `src/auth-pages.ts`; the three copies exist because they run in three
 * different runtimes. Keep the copy and palette in sync when changing one.
 */

const STYLE = `:root{color-scheme:light}
*{box-sizing:border-box}
body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;
background:radial-gradient(900px 500px at 50% -20%,#fff 0%,#eef2f8 60%,#e3eaf4 100%);color:#0f172a;
font:15px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",sans-serif;-webkit-font-smoothing:antialiased}
.card{position:relative;overflow:hidden;width:min(100%,420px);padding:34px 28px 30px;text-align:center;
background:#fff;border:1px solid #e2e8f0;border-radius:16px;
box-shadow:0 20px 50px rgba(15,23,42,.12),0 8px 20px rgba(15,23,42,.06)}
.card::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;
background:linear-gradient(90deg,#2955c9 0%,#3772ff 38%,#3bb273 72%,#e6a830 100%)}
.badge{display:flex;align-items:center;justify-content:center;width:44px;height:44px;margin:0 auto 16px;border-radius:999px}
.badge svg{width:22px;height:22px}
[data-tone=ok] .badge{background:rgba(59,178,115,.14);color:#2e8f5c}
[data-tone=warn] .badge{background:rgba(223,41,53,.12);color:#b81f2a}
.eyebrow{margin:0 0 6px;font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#2955c9}
h1{margin:0 0 10px;font-size:23px;line-height:1.25;letter-spacing:-.01em}
.lead{margin:0;color:#475569}
.steps{margin:18px 0 0;padding:0;list-style:none;text-align:left;border-top:1px solid #e2e8f0}
.steps li{position:relative;margin:0;padding:10px 0 0 18px;font-size:13.5px;color:#475569}
.steps li:first-child{padding-top:14px}
.steps li::before{content:"";position:absolute;left:2px;top:18px;width:5px;height:5px;border-radius:999px;background:#cbd5e1}
.steps li:first-child::before{top:22px}
.hint{margin:16px 0 0;font-size:12.5px;color:#64748b}
code{font:600 12.5px/1.4 ui-monospace,"SF Mono",Menlo,monospace;background:#f3f6fb;border:1px solid #e2e8f0;border-radius:5px;padding:2px 5px;overflow-wrap:anywhere;-webkit-box-decoration-break:clone;box-decoration-break:clone}
@media (max-width:400px){.card{padding:28px 20px 24px}h1{font-size:21px}}`;

const CHECK_ICON =
  `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>`;
const ALERT_ICON =
  `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.5h.01"/></svg>`;

export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]!,
  );
}

/**
 * Renders one self-contained Tui page — no external CSS, fonts, or images.
 *
 * `lead`, `steps`, `hint`, and `head` are trusted HTML so copy can carry
 * `<code>` spans; the title is escaped. Escape request-derived text at the call
 * site.
 */
function arcadePage(options: {
  tone: "ok" | "warn";
  title: string;
  lead: string;
  steps?: string[];
  hint?: string;
  head?: string;
  body?: string;
}): string {
  const steps = options.steps ?? [];
  const list = steps.length === 0
    ? ""
    : `<ul class="steps">${steps.map((step) => `<li>${step}</li>`).join("")}</ul>`;
  const hint = options.hint ? `<p class="hint">${options.hint}</p>` : "";
  const icon = options.tone === "ok" ? CHECK_ICON : ALERT_ICON;
  const titleText = escapeHtml(options.title);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Tui — ${titleText}</title>
${options.head ?? ""}
<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="${options.tone}">
<span class="badge">${icon}</span>
<p class="eyebrow">Tui</p>
<h1>${titleText}</h1>
<p class="lead">${options.lead}</p>
${list}
${hint}
</main>
${options.body ?? ""}
</body>
</html>`;
}

/**
 * The page that carries the browser back to the CLI's listener. A page rather
 * than a `302` on purpose: the redirect has to happen from the browser that
 * holds the session cookie, and a self-redirecting document also leaves
 * something readable behind if the listener is already gone.
 *
 * `url` goes into the inline script verbatim (JSON-quoted, so a quote or a
 * `</script>` in it cannot break out) and HTML-escaped into the `<meta refresh>`
 * copy kept for browsers with scripting turned off.
 */
export function handoffRedirectPage(url: string): string {
  const script = JSON.stringify(url).replace(/<\//g, "<\\/");
  return arcadePage({
    tone: "ok",
    title: "Signing you in",
    lead: "Handing your session back to Tui. This tab closes itself out in a moment.",
    hint: "Nothing happening? <code>Ctrl+C</code> in your terminal and run the sign-in command again.",
    head: `<meta http-equiv="refresh" content="0;url=${escapeHtml(url)}">`,
    body: `<script>location.replace(${script})</script>`,
  });
}

/**
 * No browser session to hand over: the user reached `/cli/handoff` directly, or
 * signed out in between. Names the command that starts a real handoff.
 */
export function signInRequiredPage(): string {
  return arcadePage({
    tone: "warn",
    title: "No signed-in session to hand over",
    lead: "This link only works right after signing in with Google or GitHub in this browser.",
    steps: [
      "Run <code>gamepigeon auth oauth google</code> (or <code>github</code>) in your terminal.",
      "Finish the provider's consent screen in the tab it opens.",
    ],
    hint: "Prefer a password? <code>gamepigeon auth login</code> signs in the same account.",
  });
}

/** The `next` target failed the localhost check, so nothing was attached to it. */
export function untrustedTargetPage(): string {
  return arcadePage({
    tone: "warn",
    title: "That handoff target isn't allowed",
    lead:
      "Tui only hands a session to a local listener — a plain <code>http</code> URL on <code>127.0.0.1</code> or <code>localhost</code>.",
    steps: [
      "Start the sign-in from the CLI so it publishes its own listener address.",
      "Run <code>gamepigeon auth oauth google</code> (or <code>github</code>) again.",
    ],
    hint: "",
  });
}

