import { getMigrations } from "better-auth/db/migration";
import {
  createAuth,
  isOAuthProvider,
  oauthCredentials,
  OAUTH_PROVIDERS,
  trustedOrigins,
  type AuthEnv,
  type OAuthProvider,
} from "./auth";
import {
  handoffRedirectPage,
  signInRequiredPage,
  unsupportedProviderPage,
  untrustedTargetPage,
} from "./handoff-page";

/** Every handoff response carries a session token, so none of them may be cached. */
function htmlResponse(status: number, body: string): Response {
  return new Response(body, {
    status,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "referrer-policy": "no-referrer",
    },
  });
}

/**
 * The only handoff targets a session token is attached to: a plain-`http` URL on
 * the loopback host, which only a process on the user's own machine can serve.
 * `https` is excluded on purpose — the token is meant for a local listener, and
 * anything answering over TLS is not one.
 */
function localHandoffTarget(next: string | null): URL | null {
  if (!next) return null;
  let url: URL;
  try {
    url = new URL(next);
  } catch {
    return null;
  }
  if (url.protocol !== "http:") return null;
  return url.hostname === "127.0.0.1" || url.hostname === "localhost" ? url : null;
}

/**
 * The literal session token, read from the request's cookie rather than from
 * whatever shape `getSession` happens to return: the CLI spends this value as a
 * bearer credential, so it has to be the exact signed cookie better-auth issued.
 */
function sessionCookieToken(request: Request): string | null {
  const header = request.headers.get("cookie");
  if (!header) return null;
  const cookies = new Map<string, string>();
  for (const part of header.split(";")) {
    const separator = part.indexOf("=");
    if (separator === -1) continue;
    cookies.set(part.slice(0, separator).trim(), part.slice(separator + 1).trim());
  }
  // better-auth's default name, plus the `__Secure-` prefix it adds when the
  // deployment's base URL is https.
  const raw = cookies.get("better-auth.session_token")
    ?? cookies.get("__Secure-better-auth.session_token");
  if (!raw) return null;
  // Cookie values arrive percent-encoded; decode once so `next` carries the
  // token in the form the auth API expects it back in.
  try {
    return decodeURIComponent(raw) || null;
  } catch {
    return raw;
  }
}

/**
 * Hands the browser's session back to the CLI listener named by `next`, as a
 * self-redirecting page rather than a `302`: the redirect has to be made by the
 * browser holding the session cookie, and a page leaves something readable
 * behind when the listener has already gone away.
 */
async function handleCliHandoff(request: Request, env: AuthEnv): Promise<Response> {
  // Before the session: an untrusted target never learns whether one exists.
  const next = localHandoffTarget(new URL(request.url).searchParams.get("next"));
  if (!next) return htmlResponse(400, untrustedTargetPage());

  const auth = createAuth(env);
  let signedIn = false;
  try {
    const session = await auth.api.getSession({ headers: request.headers });
    signedIn = Boolean(session?.user);
  } catch {
    // An unreadable or expired session is "not signed in", not a 500.
    signedIn = false;
  }
  const token = sessionCookieToken(request);
  if (!signedIn || !token) return htmlResponse(401, signInRequiredPage());

  next.searchParams.set("token", token);
  return htmlResponse(200, handoffRedirectPage(next.toString()));
}

/**
 * Starts a provider sign-in for the CLI. The provider handshake stays here (the
 * client secret never leaves the Worker) and lands back on `/cli/handoff`, which
 * is same-origin and therefore always a trusted callback.
 */
async function handleCliOAuth(request: Request, env: AuthEnv): Promise<Response> {
  const url = new URL(request.url);
  const provider = url.searchParams.get("provider");
  if (!isOAuthProvider(provider)) {
    return htmlResponse(400, unsupportedProviderPage(OAUTH_PROVIDERS));
  }
  if (!oauthCredentials(env, provider)) {
    return Response.json(
      { error: `${provider} sign-in is not configured on this deployment.` },
      { status: 503, headers: { "cache-control": "no-store" } },
    );
  }
  const next = localHandoffTarget(url.searchParams.get("next"));
  if (!next) return htmlResponse(400, untrustedTargetPage());

  return startSocialSignIn(request, env, provider, next.toString());
}

async function startSocialSignIn(
  request: Request,
  env: AuthEnv,
  provider: OAuthProvider,
  next: string,
): Promise<Response> {
  const base = env.BETTER_AUTH_URL || new URL(request.url).origin;
  const handoff = new URL("/cli/handoff", base);
  handoff.searchParams.set("next", next);
  // Failures come back to the CLI too, so a cancelled consent screen ends the
  // terminal's wait immediately instead of timing it out.
  const errorRelay = new URL("/cli/oauth-error", base);
  errorRelay.searchParams.set("next", next);

  let started: Response;
  try {
    started = await createAuth(env).api.signInSocial({
      body: {
        provider,
        callbackURL: handoff.toString(),
        errorCallbackURL: errorRelay.toString(),
      },
      headers: request.headers,
      asResponse: true,
    });
  } catch {
    return Response.json(
      { error: `Could not start ${provider} sign-in.` },
      { status: 502, headers: { "cache-control": "no-store" } },
    );
  }

  const payload = await started.json<{ url?: string }>().catch(() => null);
  if (!started.ok || !payload?.url) {
    return Response.json(
      { error: `Could not start ${provider} sign-in.` },
      { status: 502, headers: { "cache-control": "no-store" } },
    );
  }
  const headers = new Headers({ location: payload.url, "cache-control": "no-store" });
  // The OAuth state lives in a cookie (see `account.storeStateStrategy`), so the
  // redirect has to carry whatever better-auth just set.
  const setCookies = started.headers.getSetCookie?.() ?? [];
  for (const cookie of setCookies.length > 0 ? setCookies : [started.headers.get("set-cookie")]) {
    if (cookie) headers.append("set-cookie", cookie);
  }
  return new Response(null, { status: 302, headers });
}

/**
 * Relays a failed provider sign-in to the CLI listener, which turns `error` /
 * `error_description` into a page and a message in the terminal. Only loopback
 * targets, same as the handoff itself.
 */
function handleCliOAuthError(request: Request): Response {
  const url = new URL(request.url);
  const next = localHandoffTarget(url.searchParams.get("next"));
  if (!next) return htmlResponse(400, untrustedTargetPage());
  next.searchParams.set("error", url.searchParams.get("error") || "sign_in_failed");
  const description = url.searchParams.get("error_description");
  if (description) next.searchParams.set("error_description", description);
  return new Response(null, {
    status: 302,
    headers: { location: next.toString(), "cache-control": "no-store" },
  });
}

function authCors(request: Request, response: Response, env: AuthEnv): Response {
  const origin = request.headers.get("origin");
  if (!origin || !trustedOrigins(env).includes(origin)) return response;
  const headers = new Headers(response.headers);
  headers.set("access-control-allow-origin", origin);
  headers.set("access-control-allow-credentials", "true");
  headers.set("access-control-expose-headers", "set-auth-token");
  headers.append("vary", "Origin");
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

export default {
  async fetch(request: Request, env: AuthEnv): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname.startsWith("/api/auth/") && request.method === "OPTIONS") {
      const origin = request.headers.get("origin");
      if (!origin || !trustedOrigins(env).includes(origin)) return new Response(null, { status: 403 });
      return authCors(request, new Response(null, {
        status: 204,
        headers: {
          "access-control-allow-headers": "content-type, authorization",
          "access-control-allow-methods": "GET, POST, OPTIONS",
        },
      }), env);
    }

    if (url.pathname === "/migrate" && request.method === "POST") {
      if (
        !env.MIGRATION_SECRET
        || request.headers.get("authorization") !== `Bearer ${env.MIGRATION_SECRET}`
      ) {
        return Response.json(
          { error: "Unauthorized" },
          { status: 401, headers: { "www-authenticate": "Bearer" } },
        );
      }
      const auth = createAuth(env);
      const { toBeCreated, toBeAdded, runMigrations } = await getMigrations(auth.options);
      if (toBeCreated.length === 0 && toBeAdded.length === 0) {
        return Response.json({ message: "No migrations needed" });
      }
      await runMigrations();
      return Response.json({
        message: "Migrations completed",
        created: toBeCreated.map((table) => table.table),
        added: toBeAdded.map((table) => table.table),
      });
    }

    if (url.pathname === "/" && request.method === "GET") {
      return Response.json({
        service: "tui-gamepigeon-auth",
        ok: true,
        authBasePath: "/api/auth",
      });
    }

    return authCors(request, await createAuth(env).handler(request), env);
  },
} satisfies ExportedHandler<AuthEnv>;

import { afterEach, expect, test } from "bun:test";
import { existsSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runAuthCommand } from "./auth.js";

const argv = process.argv;
const home = process.env.HOME;
const authUrl = process.env.GAMEPIGEON_AUTH_URL;
const fetch = globalThis.fetch;
const prompt = globalThis.prompt;

afterEach(() => {
  process.argv = argv;
  process.env.HOME = home;
  if (authUrl === undefined) delete process.env.GAMEPIGEON_AUTH_URL;
  else process.env.GAMEPIGEON_AUTH_URL = authUrl;
  globalThis.fetch = fetch;
  globalThis.prompt = prompt;
});

test("successful password login returns only pseudonymous analytics context", async () => {
  const testHome = mkdtempSync(join(tmpdir(), "gamepigeon-auth-"));
  process.env.HOME = testHome;
  process.env.GAMEPIGEON_AUTH_URL = "https://auth.example";
  const answers = ["person@example.com", "secret"];
  globalThis.prompt = () => answers.shift() ?? "";
  globalThis.fetch = Object.assign(
    async () => new Response(JSON.stringify({
      user: { id: "usr_test", email: "person@example.com" },
    }), {
      status: 200,
      headers: { "set-auth-token": "session-secret" },
    }),
    { preconnect: fetch.preconnect },
  );

  try {
    await expect(runAuthCommand("login")).resolves.toEqual({
      kind: "signed_in",
      method: "password",
      userId: "usr_test",
    });
    expect(readFileSync(join(testHome, ".tui-gamepigeon", "backend.conf"), "utf8"))
      .toBe("https://api.runretroarcade.com\nsession-secret\n");

    await runAuthCommand("logout");
    expect(existsSync(join(testHome, ".tui-gamepigeon", "auth.json"))).toBe(false);
    expect(existsSync(join(testHome, ".tui-gamepigeon", "backend.conf"))).toBe(false);
  } finally {
    rmSync(testHome, { recursive: true, force: true });
  }
