test("the callback listener answers the readiness probe and takes a glued-on token", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");

    // Some hosted redirects append `?token=` to a callback that already carried
    // `?state=`, so the second `?` has to read as another `&`.
    const landing = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce?token=session-secret`,
    );
    expect(landing.status).toBe(200);
    expect(landing.headers.get("cache-control")).toBe("no-store");
    expect(await landing.text()).toContain("signed in");
    await expect(callback.token).resolves.toBe("session-secret");
  } finally {
    callback.close();
  }
});

test("a cancelled sign-in fails the token and says so in the browser", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const landing = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce&error=access_denied`,
    );
    expect(landing.status).toBe(400);
    expect(landing.headers.get("cache-control")).toBe("no-store");
    expect(await landing.text()).toMatch(/cancelled/i);
    await expect(callback.token).rejects.toThrow(/cancelled/i);
  } finally {
    callback.close();
  }
});

test("a provider error shows an escaped reason and reports the raw one", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const landing = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?error=server_error`
        + `&error_description=Google+said+%3Cno%3E`,
    );
    expect(landing.status).toBe(400);
    const body = await landing.text();
    expect(body).toContain("Google said &lt;no&gt;");
    expect(body).not.toContain("<no>");
    await expect(callback.token).rejects.toThrow("Google said <no>");
  } finally {
    callback.close();
  }
});

test("a taken port falls back to a free one before ready resolves", async () => {
  const occupied = startOAuthCallbackServer(0);
  await occupied.ready;
  const callback = startOAuthCallbackServer(occupied.port);
  await callback.ready;
  try {
    expect(callback.port).not.toBe(occupied.port);
    expect(callback.port).toBeGreaterThan(0);
    expect(await (await fetch(`http://127.0.0.1:${callback.port}/auth/ping`)).text()).toBe("ok");
  } finally {
    callback.close();
    occupied.close();
  }
});

test("Arc and Dia get a real tab instead of a Little Arc window", () => {
  expect(isArcBundle("company.thebrowser.Browser")).toBe(true);
  expect(isArcBundle("company.thebrowser.dia")).toBe(true);
  expect(isArcBundle("com.google.Chrome")).toBe(false);
  expect(isArcBundle("com.apple.Safari")).toBe(false);

  const url = "https://auth.example/cli/oauth?provider=google&next=http%3A%2F%2F127.0.0.1%3A3210";
  const script = arcTabScript("company.thebrowser.Browser", url);
  expect(script).toContain('tell application id "company.thebrowser.Browser"');
  expect(script).toContain(`tell front window to make new tab with properties {URL:"${url}"}`);
  // A quote in the URL must not be able to close the AppleScript string.
  expect(arcTabScript("company.thebrowser.dia", 'https://e/?a="b"')).toContain('a=\\"b\\"');
});

test("browser sign-in only accepts the providers the Worker supports", async () => {
  await expect(runAuthCommand("oauth", "twitter")).rejects.toThrow(/oauth \[google\|github\]/);
  await expect(runAuthCommand("oauth")).rejects.toThrow(/oauth \[google\|github\]/);
});
