import { env } from "cloudflare:workers";
import { describe, expect, test } from "vitest";
import { handoffRedirectPage } from "../src/handoff-page";
import worker from "../src/index";

const base = "https://auth.runretroarcade.com";
const localNext = "http://127.0.0.1:3210/auth/callback?state=nonce";

const withGoogle = {
  GOOGLE_CLIENT_ID: "google-test-id",
  GOOGLE_CLIENT_SECRET: "google-test-secret",
};

function get(
  path: string,
  options: { headers?: HeadersInit; env?: Partial<Cloudflare.Env> } = {},
): Promise<Response> {
  return worker.fetch(
    new Request(`${base}${path}`, { headers: options.headers }),
    { ...env, ...options.env },
  );
}

describe("GET /cli/oauth", () => {
  test("refuses providers the Worker does not sign in with", async () => {
    const response = await get(
      `/cli/oauth?provider=twitter&next=${encodeURIComponent(localNext)}`,
      { env: withGoogle },
    );

    expect(response.status).toBe(400);
    expect(await response.text()).toMatch(/google/i);
  });

  test("reports a provider with no app credentials as unavailable", async () => {
    const response = await get(`/cli/oauth?provider=github&next=${encodeURIComponent(localNext)}`, {
      env: withGoogle,
    });

    expect(response.status).toBe(503);
    expect(await response.text()).toMatch(/not configured/i);
  });

  test.each([
    ["a public https target", "https://evil.example/steal"],
    ["another host over http", "http://evil.example/steal"],
    ["a host that only looks local", "http://127.0.0.1.evil.example/steal"],
    ["credentials pointing elsewhere", "http://127.0.0.1@evil.example/steal"],
    ["a non-http scheme", "javascript:alert(1)"],
    ["nothing at all", ""],
  ])("refuses %s before starting sign-in", async (_label, next) => {
    const response = await get(
      `/cli/oauth?provider=google${next ? `&next=${encodeURIComponent(next)}` : ""}`,
      { env: withGoogle },
    );

    expect(response.status).toBe(400);
  });
});

describe("GET /cli/handoff", () => {
  test.each([
    ["a public https target", "https://evil.example/steal"],
    ["another host over http", "http://evil.example/steal"],
    ["a host that only looks local", "http://localhost.evil.example/steal"],
    ["nothing at all", ""],
  ])("refuses %s without looking at the session", async (_label, next) => {
    const response = await get(`/cli/handoff${next ? `?next=${encodeURIComponent(next)}` : ""}`, {
      headers: { cookie: "better-auth.session_token=would-be-leaked" },
    });

    expect(response.status).toBe(400);
    expect(await response.text()).not.toContain("would-be-leaked");
  });

  test("asks a signed-out browser to start from the CLI", async () => {
    const response = await get(`/cli/handoff?next=${encodeURIComponent(localNext)}`);

    expect(response.status).toBe(401);
    expect(await response.text()).toMatch(/oauth/i);
  });

  test("treats a cookie with no matching session as signed out", async () => {
    const response = await get(`/cli/handoff?next=${encodeURIComponent(localNext)}`, {
      headers: { cookie: "better-auth.session_token=not-a-real-session.signature" },
    });

    expect(response.status).toBe(401);
    expect(await response.text()).toMatch(/oauth/i);
  });
});

describe("the handoff page", () => {
  test("carries the target URL for scripted and unscripted browsers", () => {
    const page = handoffRedirectPage("http://127.0.0.1:3210/auth/callback?state=nonce&token=abc.1");

    // Literal for the redirect that actually runs...
    expect(page).toContain(
      'location.replace("http://127.0.0.1:3210/auth/callback?state=nonce&token=abc.1")',
    );
    // ...escaped for the scripting-disabled fallback.
    expect(page).toContain(
      '<meta http-equiv="refresh" content="0;url=http://127.0.0.1:3210/auth/callback?state=nonce&amp;token=abc.1">',
    );
  });

  test("cannot be broken out of by a target that carries markup", () => {
    const page = handoffRedirectPage('http://127.0.0.1:3210/auth/callback?token="</script><x>');

    expect(page).not.toContain("</script><x>");
    expect(page).toContain("&lt;/script&gt;&lt;x&gt;");
  });
});

